  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When a product's production in a quarter is less than that quarter's contract reservation, is the shortfall (backorder) allowed to be carried over and delivered in a later quarter (incurring the delay compensation), or must each quarter's contract be fully met from that quarter's production with no backorders permitted?"
  ],
  "rationale": "The response asks for a single policy choice regarding whether backorders are permitted or if production must fully meet quarterly contracts."
}

